use std::rc::Rc;use std::cell::RefCell;struct BSTIterator{st:Vec<Rc<RefCell<TreeNode>>>}impl BSTIterator{fn new(root:Option<Rc<RefCell<TreeNode>>>)->Self{let mut x=Self{st:vec![]};x.push(root);x}fn push(&mut self,mut n:Option<Rc<RefCell<TreeNode>>>){while let Some(x)=n{n=x.borrow().left.clone();self.st.push(x);}}fn next(&mut self)->i32{let n=self.st.pop().unwrap();let b=n.borrow();let v=b.val;let r=b.right.clone();drop(b);self.push(r);v}fn has_next(&self)->bool{!self.st.is_empty()}}
